"use client";

import { useLayoutEffect } from "react";
import { getGsap } from "@/lib/motion";

export function MotionController() {
  useLayoutEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

    const { gsap } = getGsap();
    const context = gsap.context(() => {
      gsap.from(".hero h1", { autoAlpha: 0, y: 34, duration: 0.9, ease: "power3.out", delay: 0.1 });
      gsap.from(".hero-meta", { autoAlpha: 0, y: 16, duration: 0.65, ease: "power2.out", delay: 0.5 });
      gsap.from(".hero-image", { scale: 1.06, duration: 1.2, ease: "power2.out" });
      gsap.to(".hero-image", { yPercent: 7, ease: "none", scrollTrigger: { trigger: ".hero", start: "top top", end: "bottom top", scrub: true } });

      [".about-content", ".event-feature", ".people-stage", ".project-feature"].forEach((selector) => {
        gsap.from(selector, { autoAlpha: 0, y: 44, duration: 0.85, ease: "power3.out", scrollTrigger: { trigger: selector, start: "top 82%", once: true } });
      });

      gsap.from(".moment-wall .photo-slot", { autoAlpha: 0, scale: 0.96, stagger: 0.08, duration: 0.7, ease: "power2.out", scrollTrigger: { trigger: ".moment-wall", start: "top 78%", once: true } });
      gsap.from(".join-cta > div", { autoAlpha: 0, y: 34, duration: 0.8, ease: "power3.out", scrollTrigger: { trigger: ".join-cta", start: "top 75%", once: true } });
    });

    return () => context.revert();
  }, []);

  return null;
}
